<?php require 'functions.php';require_login();$id=(int)($_GET['id']??0);$stmt=$conn->prepare('SELECT * FROM items WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$item=$stmt->get_result()->fetch_assoc();if(!$item||$item['user_id']==$_SESSION['user']['id'])redirect('browse.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$message=trim($_POST['message']??'');if(strlen($message)<10)$error='Please add at least a short description that helps verify ownership.';else{$uid=$_SESSION['user']['id'];$q=$conn->prepare('SELECT id FROM claims WHERE item_id=? AND claimant_id=?');$q->bind_param('ii',$id,$uid);$q->execute();if($q->get_result()->num_rows)$error='You already submitted a claim for this item.';else{$q=$conn->prepare('INSERT INTO claims(item_id,claimant_id,message) VALUES(?,?,?)');$q->bind_param('iis',$id,$uid,$message);$q->execute();flash('success','Claim request sent to the listing owner.');redirect('browse.php');}}}$page_title='Claim item';require 'header.php'; ?>
<div class="card auth-card" style="max-width:620px"><div class="card-body p-4 p-md-5"><p class="text-primary fw-semibold small mb-1">CLAIM REQUEST</p><h1 class="h3 fw-bold">Is “<?=e($item['title'])?>” yours?</h1><p class="text-secondary">Describe a detail only the owner would know. The owner can then contact you safely.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><label class="form-label">Why do you believe it is yours? *</label><textarea required name="message" class="form-control" rows="5" placeholder="For example: describe a unique mark, contents, or where you lost it."><?=e($_POST['message']??'')?></textarea><button class="btn btn-primary mt-3">Send claim request</button></form></div></div><?php require 'footer.php'; ?>
